<?php namespace App\Services; use Illuminate\Support\Facades\DB; class WorkflowEngine { public function run(int $workflowId,array $context=[]): int { $w=DB::table('farast_workflows')->find($workflowId); if(!$w || !$w->enabled) throw new \RuntimeException('Workflow is disabled or missing.'); $id=DB::table('farast_workflow_runs')->insertGetId(['workflow_id'=>$workflowId,'status'=>'running','context'=>json_encode($context),'started_at'=>now(),'created_at'=>now(),'updated_at'=>now()]); try { foreach(json_decode($w->steps,true)?:[] as $step){$this->step($step,$context);} DB::table('farast_workflow_runs')->where('id',$id)->update(['status'=>'completed','finished_at'=>now(),'updated_at'=>now()]); } catch(\Throwable $e){DB::table('farast_workflow_runs')->where('id',$id)->update(['status'=>'failed','error'=>$e->getMessage(),'finished_at'=>now(),'updated_at'=>now()]);throw $e;} return $id; } private function step(array $s,array $c):void { if(($s['action']??'')==='notify' && !empty($c['user_id'])) DB::table('farast_notifications')->insert(['user_id'=>$c['user_id'],'type'=>'workflow','title'=>$s['title']??'اجرای گردش‌کار','body'=>$s['message']??'گردش‌کار اجرا شد.','data'=>json_encode($c),'created_at'=>now(),'updated_at'=>now()]); } }